/* eslint-env serviceworker */

/**
 * SIPROCOM SGS service worker.
 *
 * Hand-written rather than generated by vite-plugin-pwa: that plugin builds a
 * precache manifest at build time, and the version tracking Vite 8 was not
 * something to gamble the build on. Everything here is runtime caching, which
 * needs no manifest and no build integration.
 *
 * Three strategies, one per kind of request:
 *
 *   navigations   network first, fall back to the cached shell. An SPA has one
 *                 HTML document, so the fallback is always index.html and the
 *                 router sorts out the path once React is up.
 *   hashed assets cache first. /assets/index-A1b2C3.js is immutable by
 *                 construction; if the content changes the filename changes,
 *                 so a hit can never be stale.
 *   API GETs      network first, fall back to cache, and only for the reference
 *                 data listed in CACHEABLE_API. Never for /auth, so a signed-out
 *                 session can not be served someone else's cached data.
 *
 * Writes are deliberately NOT handled here. Background Sync is Chromium-only
 * and replays outside the app, where it cannot show the user a conflict. The
 * queue lives in src/lib/offline/queue.js instead, where it can.
 */

const VERSION = 'sgs-v1';
const SHELL_CACHE = `${VERSION}-shell`;
const ASSET_CACHE = `${VERSION}-assets`;
const API_CACHE = `${VERSION}-api`;

/** Enough to boot the app with no network at all. */
const SHELL = ['/', '/index.html', '/manifest.webmanifest', '/icon.svg', '/favicon.svg'];

/**
 * Reference data worth reading offline. Deliberately a whitelist: /auth is
 * absent so credentials and identity are never served from cache, and the
 * report endpoints are absent because a stale valuation shown as current is
 * worse than an honest error.
 */
const CACHEABLE_API = [/\/api\/products/, /\/api\/categories/, /\/api\/suppliers/, /\/api\/stock(\?|$|\/)/];

const isHashedAsset = (url) => url.pathname.startsWith('/assets/');

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // addAll rejects the whole batch if any single entry 404s, which would
      // leave the worker uninstalled and the app with no offline mode at all.
      await Promise.allSettled(SHELL.map((path) => cache.add(path)));
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([SHELL_CACHE, ASSET_CACHE, API_CACHE]);
      const names = await caches.keys();
      await Promise.all(names.filter((n) => !keep.has(n)).map((n) => caches.delete(n)));
      await self.clients.claim();
    })()
  );
});

/** Cache-first: for content whose URL changes whenever the content does. */
async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;

  const response = await fetch(request);
  if (response.ok) cache.put(request, response.clone());
  return response;
}

/** Network-first: fresh when possible, cached when the network is gone. */
async function networkFirst(request, cacheName, fallback) {
  const cache = await caches.open(cacheName);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch (error) {
    const hit = await cache.match(request, { ignoreSearch: false });
    if (hit) return hit;
    if (fallback) {
      const shell = await caches.open(SHELL_CACHE);
      const shellHit = await shell.match(fallback);
      if (shellHit) return shellHit;
    }
    throw error;
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Only GET is cacheable. A POST reaching here offline must fail fast so the
  // app's queue catches it, rather than being answered from a cache.
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, SHELL_CACHE, '/index.html'));
    return;
  }

  if (isHashedAsset(url)) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  if (url.pathname.startsWith('/api/')) {
    if (CACHEABLE_API.some((re) => re.test(url.pathname + url.search))) {
      event.respondWith(networkFirst(request, API_CACHE));
    }
    return;
  }

  if (SHELL.includes(url.pathname)) {
    event.respondWith(networkFirst(request, SHELL_CACHE));
  }
});

/**
 * Lets the page drop cached API responses on sign-out. Without this, the next
 * person to use the machine could read the previous session's stock and prices
 * from cache before the first network call returns.
 */
self.addEventListener('message', (event) => {
  if (event.data === 'sgs:clear-api-cache') {
    event.waitUntil(caches.delete(API_CACHE));
  }
  if (event.data === 'sgs:skip-waiting') {
    self.skipWaiting();
  }
});
